<script setup>
import { ref,watch,onMounted,computed } from 'vue';import {useRoute} from 'vue-router';import { doctorService } from '../../../services/doctors';import { useDoctorStore } from '../../../stores/doctors';import { useClinicContextStore } from '../../../stores/clinicContext';import FormErrors from '../../../components/ui/FormErrors.vue';import DoctorLeavePanel from '../../../components/doctors/DoctorLeavePanel.vue';
const store=useDoctorStore(),context=useClinicContextStore();const requestedBranch=Number(useRoute().query.branch_id);const branch=ref(store.doctor.branches.some(b=>b.id===requestedBranch)?requestedBranch:store.doctor.display_branch_id),days=ref([]),rows=ref([]),busy=ref(false),error=ref(null),editing=ref(false),notice=ref('');const names=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
async function load(){busy.value=true;error.value=null;editing.value=false;try{rows.value=(await doctorService.schedule(store.doctor.id,branch.value)).data.data;days.value=names.map((name,index)=>{const saved=rows.value.find(r=>r.day_of_week===index+1);return{day_of_week:index+1,is_available:saved?.is_available||false,start_time:saved?.start_time?.slice(0,5)||'08:00',end_time:saved?.end_time?.slice(0,5)||'16:00',break_start:saved?.break_start?.slice(0,5)||'',break_end:saved?.break_end?.slice(0,5)||''};});}catch(e){error.value=e;}finally{busy.value=false;}}
async function save(){busy.value=true;error.value=null;try{await doctorService.saveSchedule(store.doctor.id,{branch_id:branch.value,days:days.value});await load();notice.value='Working schedule saved.';}catch(e){error.value=e;}finally{busy.value=false;}}
const orderedDays=computed(()=>[6,7,1,2,3,4,5].map(day=>days.value.find(d=>d.day_of_week===day)).filter(Boolean));watch(branch,load);onMounted(load);
</script>
<template><section class="clinic-panel"><div class="clinic-card-heading"><div><h2>Weekly working schedule</h2><p class="hint mt-2">Times are in {{context.data.clinic.timezone}}.</p></div><button v-if="context.can('doctors.schedule.update') && !editing" class="btn" :disabled="busy" @click="editing=true">Edit Schedule</button></div><label class="field max-w-sm mb-5">Schedule branch<select v-model="branch"><option v-for="b in store.doctor.branches" :key="b.id" :value="b.id">{{b.name}}</option></select></label><p v-if="notice" class="clinic-trial" role="status">{{notice}}</p><FormErrors :error="error"/><button v-if="error && !editing" class="btn-secondary" @click="load">Try again</button><p v-if="busy" class="empty-state">Loading schedule...</p><template v-else><form v-if="editing" @submit.prevent="save"><div v-for="day in orderedDays" :key="day.day_of_week" class="doctor-schedule-row"><label class="doctor-day"><input v-model="day.is_available" type="checkbox">{{names[day.day_of_week-1]}}</label><template v-if="day.is_available"><label class="field">Start<input v-model="day.start_time" type="time" required :aria-label="`${names[day.day_of_week-1]} start`"></label><label class="field">End<input v-model="day.end_time" type="time" required :aria-label="`${names[day.day_of_week-1]} end`"></label><label class="field">Break start<input v-model="day.break_start" type="time" :aria-label="`${names[day.day_of_week-1]} break start`"></label><label class="field">Break end<input v-model="day.break_end" type="time" :aria-label="`${names[day.day_of_week-1]} break end`"></label></template><span v-else class="text-sm text-slate-400">Unavailable</span></div><div class="flex justify-end gap-3 mt-5"><button class="btn-secondary" type="button" @click="load">Cancel</button><button class="btn" :disabled="busy">Save Schedule</button></div></form><template v-else><p v-if="!rows.length" class="empty-state">No working schedule configured.</p><div v-for="day in orderedDays" v-else :key="day.day_of_week" class="patient-document-row"><strong>{{names[day.day_of_week-1]}}</strong><span class="text-slate-600">{{day.is_available?`${day.start_time} – ${day.end_time}`:'Unavailable'}}<small v-if="day.is_available && day.break_start" class="block mt-2 text-slate-400">Break {{day.break_start}} – {{day.break_end}}</small></span></div></template></template></section><DoctorLeavePanel/></template>
